import{_ as i,o as t,c as a,a2 as e}from"./chunks/framework.CeXt7FPx.js";const c=JSON.parse('{"title":"Services and databases","description":"","frontmatter":{},"headers":[],"relativePath":"guide/services.md","filePath":"guide/services.md"}'),n={name:"guide/services.md"};function d(h,s,o,l,p,r){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="services-and-databases" tabindex="-1">Services and databases <a class="header-anchor" href="#services-and-databases" aria-label="Permalink to &quot;Services and databases&quot;">​</a></h1><p>Databases, caches, message brokers and search engines run as services: PostgreSQL, MariaDB, MySQL, Valkey (a Redis-compatible server; in <code>tiffin.toml</code>, <code>redis</code> means Valkey too), MongoDB, Memcached (Linux and macOS), NATS, RabbitMQ, Mailpit, Meilisearch, Typesense, Qdrant and Silo (the maintained fork of MinIO for S3 storage; <code>minio</code> means Silo). Each runs on <code>127.0.0.1</code> only, on its own port, under your account.</p><h2 id="run-one" tabindex="-1">Run one <a class="header-anchor" href="#run-one" aria-label="Permalink to &quot;Run one&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 18</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # waits until it answers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # instances, ports, state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres@18</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres@18</span></span></code></pre></div><p>An <strong>instance</strong> is one data folder, named after its major version (<code>postgres@18</code>), so two projects that use PostgreSQL 18 share one server. Give an instance its own port with <code>--port</code>; it&#39;s remembered. tiffind restarts the instances that were running when it last stopped.</p><div class="tip custom-block"><p class="custom-block-title">MongoDB</p><p><code>tiffin add mongodb</code> gives you MongoDB Community Server (the newest 9.0, 8.0 and 7.0) with <code>mongod</code> and the <code>mongosh</code> shell. Each major version keeps its own data. On Linux it&#39;s MongoDB&#39;s Ubuntu 22.04 build, which needs glibc 2.35 or newer and the system&#39;s OpenSSL 3 (any current distribution); Windows on Arm runs the x64 build. Tiffin&#39;s PHP has the <code>mongodb</code> extension, off until <code>tiffin php ext enable mongodb</code>.</p></div><h2 id="ports-and-settings" tabindex="-1">Ports and settings <a class="header-anchor" href="#ports-and-settings" aria-label="Permalink to &quot;Ports and settings&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres@18</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5433</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # a running one restarts on it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres@18</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shared_buffers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 256MB</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # restarts it to read the setting</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> max_connections</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres@18</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # yours, and where its files are</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres@18</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shared_buffers</span></span></code></pre></div><p>Settings are written into the instance&#39;s <code>conf.d</code> folder (as <code>10-tiffin.conf</code>, or <code>10-tiffin.cnf</code> for MySQL and MariaDB), which PostgreSQL, MySQL, MariaDB and Valkey read after the configuration Tiffin generates. A few settings are Tiffin&#39;s own (the port, the data folder, listening on <code>127.0.0.1</code> only) and can&#39;t be set this way. Values are plain: letters, digits, spaces and <code>_ . , : / @ + % * -</code>. For anything else, put a file of your own in the same <code>conf.d</code> folder; it is never changed. A setting the server rejects keeps it from starting: <code>tiffin service logs</code> says why, and <code>tiffin service unset</code> undoes it.</p><p>In the app, a service card&#39;s <strong>Port and settings</strong> button does the same, and opens its configuration folder.</p><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Server</th><th>User</th><th>Password</th><th>Details</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>postgres</code></td><td>none</td><td>Default port 5432</td></tr><tr><td>MySQL, MariaDB</td><td><code>root</code></td><td>none</td><td>Default port 3306</td></tr><tr><td>Valkey</td><td>none</td><td>none</td><td>Redis-compatible, default port 6379</td></tr><tr><td>Meilisearch</td><td>none</td><td>no master key</td><td>Development mode, default port 7700</td></tr><tr><td>Typesense</td><td>none</td><td>API key <code>tiffin</code></td><td>Default port 8108</td></tr><tr><td>Silo (MinIO)</td><td><code>tiffin</code></td><td><code>tiffin-secret</code></td><td>Web console on <code>127.0.0.1:9001</code>, S3 on 9000</td></tr><tr><td>RabbitMQ</td><td><code>guest</code></td><td><code>guest</code></td><td>Allowed from <code>127.0.0.1</code>; vhost <code>/</code>; management UI on <code>127.0.0.1:15672</code></td></tr><tr><td>Memcached</td><td>none</td><td>none</td><td>TCP only, default port 11211, 256 MB</td></tr><tr><td>MongoDB</td><td>none</td><td>none</td><td>Default port 27017; <code>mongosh</code> comes with it</td></tr><tr><td>NATS</td><td>none</td><td>none</td><td>Default port 4222; JetStream enabled; monitor on <code>127.0.0.1:8222</code></td></tr><tr><td>Mailpit</td><td>none</td><td>none</td><td>SMTP port 1025; Web UI on <code>127.0.0.1:8025</code></td></tr><tr><td>Qdrant</td><td>none</td><td>none</td><td>REST on port 6333, gRPC on 6334, Web UI on <code>http://127.0.0.1:6333/dashboard</code></td></tr></tbody></table><p>The host is <code>127.0.0.1</code> and the port is the one <code>tiffin service list</code> shows.</p><div class="tip custom-block"><p class="custom-block-title">NATS &amp; Qdrant</p><ul><li><code>tiffin add nats</code> installs the official NATS Server (<code>nats-server</code>) with JetStream storage enabled.</li><li><code>tiffin add qdrant</code> installs Qdrant Vector Search Engine (<code>qdrant</code>) with its built-in web dashboard accessible at <code>http://127.0.0.1:6333/dashboard</code>.</li></ul></div><div class="tip custom-block"><p class="custom-block-title">Mailpit</p><p><code>tiffin add mailpit</code> provides Mailpit (<code>mailpit</code>) as a service, offering an alternate SMTP testing server with its own fast web UI at <code>http://127.0.0.1:8025</code> alongside Tiffin&#39;s built-in Mail screen.</p></div><div class="tip custom-block"><p class="custom-block-title">RabbitMQ</p><p>RabbitMQ runs on Erlang: <code>tiffin add rabbitmq</code> adds Erlang 28 too when no Erlang 28 or 27 is installed. Its node is <code>rabbit-&lt;port&gt;@localhost</code>, so on the command line <code>rabbitmqctl -n rabbit-5672@localhost status</code> (Linux and macOS; on Windows RabbitMQ&#39;s own <code>.bat</code> tools aren&#39;t put on PATH). Run one RabbitMQ version at a time: the management UI&#39;s port is fixed.</p></div><h2 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # to a timestamped .sql.gz in Tiffin&#39;s backups folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/shop.sql.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/shop.sql.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # asks first</span></span></code></pre></div><p>With one database server running, <code>tiffin db</code> uses it; otherwise pick one with <code>--service postgres@18</code>. A project&#39;s <code>tiffin.toml</code> can create its databases for you: see <a href="/tiffin/guide/projects">Projects</a>.</p><h3 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h3><p>Keep a database as it is, and go back to it after a test run, a seeder, or a migration gone wrong:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> save</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seeded</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # a label, or none for the time</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seeded</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # or the newest, without a label (asks first)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> before-restore</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # undo that restore</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snapshot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seeded</span></span></code></pre></div><p>A restore makes the database exactly what the snapshot holds: it&#39;s dropped and loaded again. What it held just before is kept as the snapshot <code>before-restore</code> first, so a restore can always be undone. If loading fails, the data is in <code>before-restore</code>.</p><p>Snapshots are kept in Tiffin&#39;s data folder, per server and database. In the app, a database&#39;s ⋯ menu on <strong>Databases</strong> has <em>Snapshots…</em>.</p><h2 id="your-app-s-env" tabindex="-1">Your app&#39;s .env <a class="header-anchor" href="#your-app-s-env" aria-label="Permalink to &quot;Your app&#39;s .env&quot;">​</a></h2><p><code>tiffin env</code> prints the lines a Laravel app needs for what Tiffin runs: <code>APP_URL</code>, the database (what the project&#39;s <code>tiffin.toml</code> asks for, else what runs), Redis, Memcached, MongoDB (<code>MONGODB_URI</code>, for <code>mongodb/laravel-mongodb</code>), Scout&#39;s search engine, the S3 disk, the mail catcher and the dumps receiver.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # in the project&#39;s folder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span></span></code></pre></div><p>Paste what you need into <code>.env</code>; Tiffin never writes to it. The app has <em>Copy .env settings</em> in a site&#39;s ⋯ menu on Projects.</p>`,28)])])}const F=i(n,[["render",d]]);export{c as __pageData,F as default};
